-- ============================================================================
-- PlayTurf — Security & Data-Integrity Fixes (run in Supabase Dashboard → SQL Editor)
-- Generated by the 2026-10-31 full-application audit.
--
-- ⚠️  REVIEW BEFORE RUNNING. Sections are independent — run (or skip) one at a
--  time and verify the app after each. Every statement is idempotent.
--
-- Sections:
--   1. Privilege escalation: block non-admins from changing profiles.role/is_admin
--   2. World-writable "service_role" policies → scoped to service_role + admins
--   3. Bookings readable by any anonymous caller → authenticated + admins only
--   4. Feedbacks insert: require the row to belong to the caller (or guest)
--   5. Booking status case normalization (app lowercase vs SQL uppercase drift)
--   6. Pitch-aware, case-insensitive overlap trigger + unique index
--   7. expire_pending_bookings(): fix case mismatch + schedule with pg_cron
-- ============================================================================

-- ---------------------------------------------------------------------------
-- SECTION 0 — Preflight: see what policies exist today
-- ---------------------------------------------------------------------------
SELECT tablename, policyname, cmd, roles, qual
FROM pg_policies
WHERE schemaname = 'public'
  AND (policyname ILIKE '%service_role%' OR tablename IN ('bookings','profiles','rate_limits','admin_logs','feedbacks'))
ORDER BY tablename, policyname;


-- ---------------------------------------------------------------------------
-- SECTION 1 — profiles: prevent self-elevation of role / is_admin
-- Root cause: "Users can update own profile" FOR UPDATE USING (auth.uid() = id)
-- has no column restriction, so any user can set their own role to super_admin.
-- ---------------------------------------------------------------------------

CREATE OR REPLACE FUNCTION public.prevent_profile_role_escalation()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  IF NEW.role IS DISTINCT FROM OLD.role
     OR COALESCE(NEW.is_admin, false) IS DISTINCT FROM COALESCE(OLD.is_admin, false) THEN

    -- auth.uid() IS NULL → dashboard SQL editor / service role: allow.
    IF auth.uid() IS NOT NULL THEN
      IF NOT EXISTS (
        SELECT 1 FROM public.profiles p
        WHERE p.id = auth.uid() AND p.role = 'super_admin'
      ) THEN
        RAISE EXCEPTION 'Only super administrators can change role or admin flags';
      END IF;
    END IF;
  END IF;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS profiles_role_guard ON public.profiles;
CREATE TRIGGER profiles_role_guard
  BEFORE UPDATE ON public.profiles
  FOR EACH ROW
  EXECUTE FUNCTION public.prevent_profile_role_escalation();

-- Belt-and-braces: also add WITH CHECK to the own-profile update policy.
DROP POLICY IF EXISTS "Users can update own profile" ON public.profiles;
CREATE POLICY "Users can update own profile"
  ON public.profiles FOR UPDATE
  USING (auth.uid() = id)
  WITH CHECK (auth.uid() = id);


-- ---------------------------------------------------------------------------
-- SECTION 2 — Content tables: policies named "service_role" currently apply
-- to EVERYONE (USING (true) with no TO clause). Anyone with the anon key can
-- insert/update/delete turfs, offers, banners, tournaments, reviews, favorites.
-- Replace with: public read + admins manage + real service_role full access.
-- ---------------------------------------------------------------------------

DO $$
DECLARE
  t text;
BEGIN
  FOREACH t IN ARRAY ARRAY['turfs','offers','banners','tournaments','reviews','favorites']
  LOOP
    EXECUTE format('DROP POLICY IF EXISTS "Allow service_role full access on %I" ON public.%I', t, t);
    EXECUTE format('DROP POLICY IF EXISTS "Service role full access on %I" ON public.%I', t, t);
    -- Admins (profiles.role admin/super_admin, or is_admin) manage these tables
    EXECUTE format($f$
      CREATE POLICY "Admins can manage %I"
        ON public.%I FOR ALL
        USING (
          EXISTS (
            SELECT 1 FROM public.profiles
            WHERE id = auth.uid()
              AND (is_admin = true OR role IN ('admin','super_admin'))
          )
        )
        WITH CHECK (
          EXISTS (
            SELECT 1 FROM public.profiles
            WHERE id = auth.uid()
              AND (is_admin = true OR role IN ('admin','super_admin'))
          )
        )
    $f$, t, t);
  END LOOP;
END $$;

-- Real service_role full access (replaces the misnamed world-open policies)
DO $$
DECLARE
  t text;
BEGIN
  FOREACH t IN ARRAY ARRAY['turfs','offers','banners','tournaments','reviews','favorites','bookings','rate_limits','admin_logs']
  LOOP
    EXECUTE format(
      'DROP POLICY IF EXISTS "svc_role_full_access_%I" ON public.%I', t, t);
    EXECUTE format($f$
      CREATE POLICY "svc_role_full_access_%I"
        ON public.%I FOR ALL
        TO service_role
        USING (true)
        WITH CHECK (true)
    $f$, t, t);
  END LOOP;
END $$;


-- ---------------------------------------------------------------------------
-- SECTION 3 — bookings: any ANONYMOUS caller could currently read/write every
-- booking (names, phones, payment ids). Keep the venue dashboard working
-- (clients are authenticated) while blocking anonymous access.
-- NOTE: the proper fix is venue-ownership columns (owner_id on turfs) so only
-- the owning client reads their venue's bookings — needs a schema change and
-- is intentionally NOT done here.
-- ---------------------------------------------------------------------------

DROP POLICY IF EXISTS "Allow service_role full access on bookings" ON public.bookings;

-- Any authenticated user can view (venue dashboard reads its court bookings;
-- replace with owner-scoped policy once ownership columns exist)
DROP POLICY IF EXISTS "Authenticated users can view bookings" ON public.bookings;
CREATE POLICY "Authenticated users can view bookings"
  ON public.bookings FOR SELECT
  TO authenticated
  USING (true);

-- Admins can manage all bookings (admin dashboard)
DROP POLICY IF EXISTS "Admins can manage bookings" ON public.bookings;
CREATE POLICY "Admins can manage bookings"
  ON public.bookings FOR ALL
  USING (
    EXISTS (
      SELECT 1 FROM public.profiles
      WHERE id = auth.uid()
        AND (is_admin = true OR role IN ('admin','super_admin'))
    )
  )
  WITH CHECK (
    EXISTS (
      SELECT 1 FROM public.profiles
      WHERE id = auth.uid()
        AND (is_admin = true OR role IN ('admin','super_admin'))
    )
  );

-- rate_limits / admin_logs: never readable/writable by clients at all
-- (the client-side rate limiter fails open when this table is unavailable —
-- that is by design; real limits belong on the server).
DROP POLICY IF EXISTS "Service role full access on rate_limits" ON public.rate_limits;
DROP POLICY IF EXISTS "Service role full access on admin_logs" ON public.admin_logs;
DROP POLICY IF EXISTS "Allow public insert on rate_limits" ON public.rate_limits;


-- ---------------------------------------------------------------------------
-- SECTION 4 — feedbacks: insert currently accepts arbitrary rows
-- WITH CHECK (true) → spam + XSS payload delivery into the admin dashboard.
-- ---------------------------------------------------------------------------

DROP POLICY IF EXISTS "Users can create feedbacks" ON public.feedbacks;
CREATE POLICY "Users can create feedbacks"
  ON public.feedbacks FOR INSERT
  TO authenticated
  WITH CHECK (user_id = auth.uid() OR user_id IS NULL);


-- ---------------------------------------------------------------------------
-- SECTION 5 — Booking status case normalization.
-- The app writes lowercase; SQL functions/RPCs write UPPERCASE. The old
-- index/trigger compared with != 'CANCELLED' (case-sensitive), so lowercase
-- 'cancelled' rows still occupied slots forever.
-- Strategy: normalize all rows to lowercase + lowercase every future write.
-- ---------------------------------------------------------------------------

-- 5.1 Normalize existing rows
UPDATE public.bookings SET status = lower(status) WHERE status <> lower(status);

-- 5.2 Force lowercase on every future write (RPCs, SQL fns, app all converge)
CREATE OR REPLACE FUNCTION public.normalize_booking_status()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
  NEW.status := lower(NEW.status);
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_bookings_status_lowercase ON public.bookings;
CREATE TRIGGER trg_bookings_status_lowercase
  BEFORE INSERT OR UPDATE OF status ON public.bookings
  FOR EACH ROW
  EXECUTE FUNCTION public.normalize_booking_status();

-- 5.3 Recreate the uniqueness index case-insensitively and pitch-aware
DROP INDEX IF EXISTS public.unique_active_booking;
CREATE UNIQUE INDEX IF NOT EXISTS unique_active_booking
ON public.bookings (turf_id, date, start_time, COALESCE(pitch_id, -1))
WHERE lower(status) <> 'cancelled' AND is_split_booking = false;


-- ---------------------------------------------------------------------------
-- SECTION 6 — Overlap trigger: case-insensitive + pitch-aware
-- The old check (a) treated lowercase 'cancelled' rows as active and
-- (b) ignored pitch_id, so booking Court 2 while Court 1 was booked failed
-- even though the app explicitly supports per-court availability.
-- ---------------------------------------------------------------------------

CREATE OR REPLACE FUNCTION public.check_booking_overlap_and_expiry()
RETURNS trigger AS $$
DECLARE
    existing_count integer;
    slot_timestamp timestamp;
    current_server_time timestamp;
BEGIN
    -- 1. Expiry Validation (Asia/Kolkata for Indian turf locations)
    IF NEW.date = to_char(timezone('Asia/Kolkata'::text, now()), 'YYYY-MM-DD') THEN
        slot_timestamp := (NEW.date || ' ' || NEW.start_time)::timestamp;
        current_server_time := timezone('Asia/Kolkata'::text, now())::timestamp;

        IF slot_timestamp <= current_server_time THEN
            RAISE EXCEPTION 'This slot has already expired and cannot be booked.';
        END IF;
    END IF;

    -- 2. Multi-hour Overlap Check — case-insensitive status, pitch-aware.
    --    A NULL-pitch booking only conflicts with other NULL-pitch bookings
    --    (matches the app: Court 1 booked, Court 2 available).
    SELECT COUNT(*) INTO existing_count
    FROM public.bookings
    WHERE turf_id = NEW.turf_id
      AND date = NEW.date
      AND lower(status) NOT IN ('cancelled')
      AND id != NEW.id
      AND pitch_id IS NOT DISTINCT FROM NEW.pitch_id
      AND (
        (NEW.start_time::time < end_time::time) AND
        (NEW.end_time::time > start_time::time)
      );

    IF existing_count > 0 THEN
        RAISE EXCEPTION 'One or more slots in this time range are already booked.';
    END IF;

    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS trg_check_booking_overlap_and_expiry ON public.bookings;
CREATE TRIGGER trg_check_booking_overlap_and_expiry
    BEFORE INSERT OR UPDATE ON public.bookings
    FOR EACH ROW
    EXECUTE FUNCTION public.check_booking_overlap_and_expiry();


-- ---------------------------------------------------------------------------
-- SECTION 7 — expire_pending_bookings(): the old version matched
-- status = 'PENDING' but the app writes lowercase 'pending' → nothing ever
-- expired, and it wrote 'CANCELLED' which the app never recognized.
-- Also schedules it every 5 minutes via pg_cron so abandoned checkouts
-- release their slots.
-- ---------------------------------------------------------------------------

CREATE OR REPLACE FUNCTION public.expire_pending_bookings()
RETURNS void
LANGUAGE plpgsql
AS $$
BEGIN
    UPDATE public.bookings
    SET status = 'cancelled'
    WHERE lower(status) = 'pending'
    AND created_at < timezone('utc'::text, now()) - interval '15 minutes';
END;
$$;

DO $$
BEGIN
    IF EXISTS (SELECT 1 FROM pg_available_extensions WHERE name = 'pg_cron') THEN
        CREATE EXTENSION IF NOT EXISTS pg_cron;
        -- Every 5 minutes
        PERFORM cron.unschedule('expire-pending-bookings')
          WHERE EXISTS (SELECT 1 FROM cron.job WHERE jobname = 'expire-pending-bookings');
        PERFORM cron.schedule(
            'expire-pending-bookings',
            '*/5 * * * *',
            'SELECT public.expire_pending_bookings()'
        );
    ELSE
        RAISE NOTICE 'pg_cron not available — schedule expire_pending_bookings() manually or via pg_cron dashboard toggle.';
    END IF;
EXCEPTION
    WHEN OTHERS THEN
        RAISE NOTICE 'Could not schedule pg_cron job: %', SQLERRM;
END $$;


